import 'package:flutter/material.dart'; import 'widgets/admin_stat_card.dart'; import 'pages/users_admin_page.dart'; import 'pages/products_admin_page.dart'; import 'pages/banners_admin_page.dart'; import 'pages/chat_admin_page.dart';
class AdminDashboard extends StatelessWidget{const AdminDashboard({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Admin Dashboard')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Pusat Pengelolaan Super-App',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),const AdminStats(),const SizedBox(height:16),_m(c,'Pengguna',Icons.people,const UsersAdminPage()),_m(c,'Produk',Icons.inventory_2,const ProductsAdminPage()),_m(c,'Banner Promo',Icons.campaign,const BannersAdminPage()),_m(c,'Chat Admin',Icons.support_agent,const ChatAdminPage())]));Widget _m(BuildContext c,String t,IconData i,Widget p)=>Card(child:ListTile(leading:Icon(i),title:Text(t),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>p))));}